    const seedPixelByte = bytes[seedY * wA + seedX];
    const polarity = seedPixelByte >= backgroundByte ? 1 : -1;
    const elevation = (byte) => polarity > 0 ? byte : 255 - byte;
    const seedNeighborhood = [];
